claims.raw:
{
  "claims": [
    {
      "quote": "Theranos Wellness Centers, currently located in 42 locations in Arizona, one in Palo Alto, California and one in Harrisburg, Pennsylvania.",
      "kind": "specific",
      "why": "A reader could check the number and locations of these wellness centers against public records."
    },
    {
      "quote": "Specifically, Theranos provided study data from 818 subjects of varying age and ethnicity, demonstrating that its system could be run accurately using only a finger stick as well as a traditional venous draw across large numbers of Theranos devices, all compared against an FDA cleared, commercially available reference method.",
      "kind": "specific",
      "why": "A third party could verify the study participant count and methodology in FDA submission documents."
    },
    {
      "quote": "Theranos’ HSV-1 studies included matrix comparison studies across 69 Theranos devices.",
      "kind": "specific",
      "why": "The exact number of devices used in the matrix comparison studies can be checked against regulatory filings."
    },
    {
      "quote": "Theranos’ HSV-1 clinical studies also included sensitivity and specificity studies with hundreds of human samples – both capillary and venous, CDC panel testing – which demonstrated 100% agreement with the results provided by CDC, low-prevalence population tests, and other studies.",
      "kind": "specific",
      "why": "The claim of 100% agreement with CDC panel testing results is a checkable statistical metric."
    },
    {
      "quote": "Theranos, Inc. is a consumer health technology company founded in 2003 by Elizabeth Holmes.",
      "kind": "specific",
      "why": "Corporate registration records can verify the founding year and founder's name."
    },
    {
      "quote": "The waiver means FDA determined the Theranos test and technology is reliable and accurate and can be used in a broader set of locations outside of a traditional CLIA certified laboratory, including Theranos Wellness Centers.",
      "kind": "specific",
      "why": "FDA regulatory determinations and waiver permissions can be verified through public agency databases."
    },
    {
      "quote": "Theranos is leading transparency in lab testing, including committing to FDA review of all of its LDTs and publishing its prices, lab proficiency testing scores, customer satisfaction scores, guest visit times, and more, to realize a system in which individuals become more engaged and early detection and prevention of disease become realities.",
      "kind": "vague",
      "why": "The assertion of leading transparency and other subjective adjectives are unverifiable marketing claims."
    },
    {
      "quote": "The FDA’s review process for 510(k) notifications is widely recognized as one of the most rigorous regulatory hurdles in the world for evaluation of the performance, accuracy, and intended use of diagnostic tests.",
      "kind": "vague",
      "why": "Phrases like most rigorous regulatory hurdles in the world represent subjective puffery."
    }
  ]
}

